// Writing Toolkit for Clixy - readable source.
//
// This is the plugin code. The installable artifact is writing-toolkit.clixy.json
// (this code embedded in a package). To install: open Clixy Settings, Plugins,
// Install, and paste the contents of the .json file.
//
// The plugin runs in a sandbox: no network, no files, no DOM, and it never sees
// your API key. AI actions go through clixy.ai, which runs the completion using
// the model and key set in Clixy Settings.

var SMALL_WORDS = new Set([
  'a', 'an', 'and', 'as', 'at', 'but', 'by', 'for', 'if', 'in', 'nor',
  'of', 'on', 'or', 'per', 'the', 'to', 'via', 'vs',
]);

function titleCaseLine(line) {
  var seenWord = false;
  return line
    .split(/(\s+)/)
    .map(function (token) {
      if (token === '' || /^\s+$/.test(token)) return token;
      var lower = token.toLowerCase();
      var isFirst = !seenWord;
      seenWord = true;
      if (!isFirst && SMALL_WORDS.has(lower)) return lower;
      return lower.charAt(0).toUpperCase() + lower.slice(1);
    })
    .join('');
}

function titleCase(text) {
  return text.split('\n').map(titleCaseLine).join('\n');
}

function bulletize(text) {
  return text
    .split('\n')
    .map(function (line) {
      var trimmed = line.trim();
      if (!trimmed) return '';
      if (/^([-*+]|\d+\.)\s/.test(trimmed)) return line; // already a list item
      return '- ' + trimmed;
    })
    .join('\n');
}

// AI actions -------------------------------------------------------------

clixy.registerAction({
  id: 'grammar',
  label: 'Fix grammar',
  description: 'Correct grammar, spelling, and punctuation, keeping meaning and Markdown',
  run: function (text) {
    return clixy.ai(
      'Correct the grammar, spelling, and punctuation in the following Markdown. ' +
        'Preserve the meaning, the voice, and all Markdown formatting. ' +
        'Return only the corrected text, with no preamble.\n\n' +
        text
    );
  },
});

clixy.registerAction({
  id: 'clarity',
  label: 'Improve clarity',
  description: 'Rewrite to be clearer and more concise',
  run: function (text) {
    return clixy.ai(
      'Rewrite the following Markdown to be clearer and more concise without losing ' +
        'meaning. Keep the Markdown formatting. Return only the rewritten text.\n\n' +
        text
    );
  },
});

clixy.registerAction({
  id: 'tone',
  label: 'Change tone',
  description: 'Rewrite in the tone set in this plugin config',
  run: function (text) {
    var tone = String(clixy.config.tone || 'Professional');
    return clixy.ai(
      'Rewrite the following Markdown in a ' +
        tone.toLowerCase() +
        ' tone. Preserve meaning and Markdown formatting. Return only the rewritten text.\n\n' +
        text
    );
  },
});

clixy.registerAction({
  id: 'summarize',
  label: 'Summarize',
  description: 'Summarize as bullet points (count set in config)',
  run: function (text) {
    var count = Number(clixy.config.summaryBullets) || 5;
    return clixy.ai(
      'Summarize the following text as at most ' +
        count +
        ' concise Markdown bullet points. Return only the bullet list.\n\n' +
        text
    );
  },
});

// Local actions (no AI, no network) --------------------------------------

clixy.registerAction({
  id: 'titlecase',
  label: 'Title case',
  description: 'Capitalize the text as a title',
  run: function (text) {
    return titleCase(text);
  },
});

clixy.registerAction({
  id: 'bulletize',
  label: 'Bulletize lines',
  description: 'Turn each non-empty line into a Markdown bullet',
  run: function (text) {
    return bulletize(text);
  },
});
